{"command": "create", "path": "/app/workspace/src/main/java/clusterdata/utils/TaskEventSource.java", "file_text": "package clusterdata.utils;

import clusterdata.datatypes.TaskEvent;
import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/**
 * SourceFunction that reads task events from a gzipped CSV file on the local
 * filesystem. Events are emitted in file order with their timestamp (converted
 * from microseconds to milliseconds) attached as the event-time.
 */
public class TaskEventSource implements SourceFunction<TaskEvent> {

    private static final long serialVersionUID = 1L;

    private final String path;
    private volatile boolean running = true;

    public TaskEventSource(String path) {
        this.path = path;
    }

    @Override
    public void run(SourceContext<TaskEvent> ctx) throws Exception {
        if (path == null) {
            throw new IllegalArgumentException("task_input path is not set");
        }
        try (InputStream in = new GZIPInputStream(new FileInputStream(path));
             BufferedReader br = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {

            String line;
            while (running && (line = br.readLine()) != null) {
                TaskEvent te = TaskEvent.fromCsv(line);
                if (te == null) continue;
                // Trace timestamps are in microseconds; Flink event-time is milliseconds.
                ctx.collectWithTimestamp(te, te.timestamp / 1000L);
            }
        }
    }

    @Override
    public void cancel() {
        running = false;
    }
}
