{"command": "create", "path": "/app/workspace/src/main/java/clusterdata/datatypes/TaskEvent.java", "file_text": "package clusterdata.datatypes;

import java.io.Serializable;

/**
 * Task event record from the Google ClusterData 2011-2 trace.
 *
 * CSV columns:
 *  0  timestamp (microseconds)
 *  1  missing info
 *  2  job id
 *  3  task index
 *  4  machine id
 *  5  event type (0=SUBMIT, 1=SCHEDULE, 2=EVICT, 3=FAIL, 4=FINISH,
 *                 5=KILL, 6=LOST, 7=UPDATE_PENDING, 8=UPDATE_RUNNING)
 *  6  user
 *  7  scheduling class
 *  8  priority
 *  9  cpu request
 * 10  memory request
 * 11  disk request
 * 12  different machines restriction
 */
public class TaskEvent implements Serializable {

    public static final int SUBMIT = 0;
    public static final int SCHEDULE = 1;
    public static final int EVICT = 2;
    public static final int FAIL = 3;
    public static final int FINISH = 4;
    public static final int KILL = 5;
    public static final int LOST = 6;
    public static final int UPDATE_PENDING = 7;
    public static final int UPDATE_RUNNING = 8;

    public long timestamp;
    public long jobId;
    public long taskIndex;
    public long machineId;
    public int eventType;
    public String user;
    public int schedulingClass;
    public int priority;
    public double cpuRequest;
    public double memoryRequest;
    public double diskRequest;
    public int differentMachines;

    public TaskEvent() {}

    public TaskEvent(long timestamp, long jobId, long taskIndex, int eventType) {
        this.timestamp = timestamp;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.eventType = eventType;
    }

    /** Parse a CSV line into a TaskEvent. Returns null for malformed lines. */
    public static TaskEvent fromCsv(String line) {
        if (line == null || line.isEmpty()) return null;
        String[] f = line.split(",", -1);
        if (f.length < 6) return null;
        try {
            TaskEvent t = new TaskEvent();
            t.timestamp = parseLong(f[0]);
            t.jobId = parseLong(f[2]);
            t.taskIndex = parseLong(f[3]);
            t.machineId = parseLong(f[4]);
            t.eventType = (int) parseLong(f[5]);
            if (f.length > 6) t.user = f[6];
            if (f.length > 7) t.schedulingClass = (int) parseLong(f[7]);
            if (f.length > 8) t.priority = (int) parseLong(f[8]);
            if (f.length > 9) t.cpuRequest = parseDouble(f[9]);
            if (f.length > 10) t.memoryRequest = parseDouble(f[10]);
            if (f.length > 11) t.diskRequest = parseDouble(f[11]);
            if (f.length > 12) t.differentMachines = (int) parseLong(f[12]);
            return t;
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private static long parseLong(String s) {
        if (s == null || s.isEmpty()) return 0L;
        return Long.parseLong(s);
    }

    private static double parseDouble(String s) {
        if (s == null || s.isEmpty()) return 0.0;
        return Double.parseDouble(s);
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "timestamp=" + timestamp +
                ", jobId=" + jobId +
                ", taskIndex=" + taskIndex +
                ", eventType=" + eventType +
                '}';
    }
}
