    /** Parse a CSV line into a JobEvent. Returns null for malformed lines. */
    public static JobEvent fromCsv(String line) {
        if (line == null || line.isEmpty()) return null;
        String[] f = line.split(",", -1);
        if (f.length < 4) return null;
        try {
            JobEvent j = new JobEvent();
            j.timestamp = parseLong(f[0]);
            j.jobId = parseLong(f[2]);
            j.eventType = (int) parseLong(f[3]);
            if (f.length > 4) j.user = f[4];
            if (f.length > 5) j.schedulingClass = (int) parseLong(f[5]);
            if (f.length > 6) j.jobName = f[6];
            if (f.length > 7) j.logicalJobName = f[7];
            return j;
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private static long parseLong(String s) {
        if (s == null || s.isEmpty()) return 0L;
        return Long.parseLong(s);
    }

    @Override
